window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[86]={"id":"086","numero":86,"titre":"Pathologie des paupières","objectifs":[{"id":"86-1","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un ectropion et connaître ses complications","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-2","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un entropion et connaître ses complications","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-3","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un ptosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-4","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies d’un ptosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"86-5","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un chalazion","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"86-6","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un orgelet","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un chalazion","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-8","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un orgelet","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-9","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir suspecter une tumeur maligne palpébrale","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"86-10","rang":"B","rubrique":"Prise en charge","titre":"Traitement du chalazion","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"86-11","rang":"A","rubrique":"Prise en charge","titre":"Traitement de l’orgelet","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-12","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer une paralysie du III et rechercher un anévrysme intra-crânien sur un ptosis douloureux","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"86-13","rang":"B","rubrique":"Epidémiologie","titre":"Savoir suspecter une imperforation des voies lacrymales du nourrisson","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0}],"astuces":[],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ptosis — bord libre de la paupière supérieure trop bas — Éliminer d'abord un dermatochalasis (simple excès de peau, bord libre normal)","detail":"<h4>CAT — ptosis : reconnaître l'<span class=\"kw-alerte\">urgence</span> vasculaire — Devant un ptosis aigu, éliminer une paralysie du III (anévrisme) et un Claude-Bernard-Horner (<span class=\"kw-etio\">dissection</span> carotidienne)</h4>","branches":[{"to":"t-dermato","label":"Bord libre en position normale, simple excès de peau","color":"blue"},{"to":"q-installation","label":"Bord libre réellement abaissé = ptosis vrai","color":"amber"}]},{"id":"t-dermato","kind":"terminal","label":"Dermatochalasis (diagnostic différentiel)","color":"blue","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Dermatochalasis</span> = excès de peau de la paupière pouvant occlure l'axe visuel, alors que la <span class=\"kw-clinique\">position du bord libre reste normale</span>.</li><li>Ce n'est pas un vrai ptosis : pas d'abaissement réel du <span class=\"kw-clinique\">bord libre de la paupière supérieure</span>.</li></ul>"},{"id":"q-installation","kind":"decision","label":"Mode d'installation du ptosis ? — Une survenue aiguë oriente vers une urgence vasculaire engageant le pronostic vital","branches":[{"to":"q-pupille","label":"Aigu","color":"red"},{"to":"t-chronique","label":"Progressif / ancien","color":"green"}]},{"id":"q-pupille","kind":"decision","label":"Anomalie pupillaire ou oculomotrice associée ? — Devant un ptosis aigu, rechercher une pathologie vasculaire","branches":[{"to":"t-III","label":"Mydriase + paralysie oculomotrice","color":"red"},{"to":"t-cbh","label":"Myosis, sans paralysie oculomotrice","color":"red"},{"to":"t-aigu-isole","label":"Non — aucune anomalie pupillaire ni oculomotrice","color":"amber"}]},{"id":"t-III","kind":"terminal","label":"Paralysie du III → suspicion de rupture d'anévrisme","color":"red","detail":"<h4>Présentation</h4><ul><li><span class=\"kw-clinique\">Ptosis unilatéral, aigu et douloureux</span> avec <span class=\"kw-clinique\">paralysie oculomotrice</span> et <span class=\"kw-clinique\">mydriase</span>.</li></ul><h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Anévrisme de l'artère communicante postérieure</span> → suspicion de <span class=\"kw-alerte\">rupture d'anévrisme</span>.</li><li>Autres atteintes du III : <span class=\"kw-clinique\">lésion</span> du <span class=\"kw-etio\">tronc cérébral</span> ou du <span class=\"kw-etio\">sinus caverneux</span>, <span class=\"kw-etio\">diabète</span>.</li></ul><h4>Conduite</h4><ul><li>Devant ce <span class=\"kw-clinique\">ptosis douloureux</span>, <span class=\"kw-alerte\">rechercher un anévrysme intra-crânien</span>.</li></ul>"},{"id":"t-cbh","kind":"terminal","label":"Claude-Bernard-Horner → suspicion de dissection carotidienne","color":"red","detail":"<h4>Présentation</h4><ul><li><span class=\"kw-clinique\">Ptosis unilatéral aigu</span> + <span class=\"kw-clinique\">myosis</span>, <span class=\"kw-clinique\">sans paralysie oculomotrice</span>.</li></ul><h4>Étiologie</h4><ul><li>Suspicion de <span class=\"kw-alerte\">dissection carotidienne</span>.</li><li>Autres : <span class=\"kw-clinique\">lésion</span> du <span class=\"kw-etio\">sinus caverneux</span>, de l'<span class=\"kw-etio\">hypothalamus</span> ou du <span class=\"kw-etio\">tronc cérébral</span>, lésion médullaire <span class=\"kw-etio\">D8-T1</span>, lésion du <span class=\"kw-etio\">ganglion stellaire</span> (<span class=\"kw-clinique\">syndrome de Pancoast</span>-Tobias).</li></ul>"},{"id":"t-aigu-isole","kind":"terminal","label":"Ptosis aigu isolé — cause aponévrotique / traumatique","color":"amber","detail":"<h4>Interprétation</h4><ul><li>Ptosis d'installation aiguë <span class=\"kw-clinique\">sans anomalie pupillaire ni oculomotrice</span> : pas de signe d'atteinte du III ni du sympathique.</li></ul><h4>Cause</h4><ul><li>Évoquer une <span class=\"kw-etio\">cause traumatique</span> par <span class=\"kw-etio\">rupture de l'aponévrose du muscle releveur</span> (y compris microtraumatismes répétés).</li></ul>"},{"id":"t-chronique","kind":"terminal","label":"Ptosis progressif / ancien — étiologies non urgentes","color":"green","detail":"<h4>Causes neurologiques</h4><ul><li><span class=\"kw-etio\">Myasthénie</span> : ptosis fluctuant, unilatéral, bilatéral ou à bascule.</li><li><span class=\"kw-etio\">Myopathie</span> : ptosis bilatéral et progressif.</li></ul><h4>Autres causes</h4><ul><li><span class=\"kw-etio\">Ptosis congénital</span> : cause myogène, la plus fréquente.</li><li><span class=\"kw-etio\">Ptosis sénile</span> : relâchement de l'<span class=\"kw-clinique\">aponévrose du releveur</span>.</li></ul>"}]},"cards":[{"i":"019d4860a9f0","n":86,"o":"86-1","u":"Diagnostic positif","t":"Reconnaître un ectropion et connaître ses complications","q":"Quelles sont les complications d'un ectropion ?","a":"<ul><li><strong>Larmoiements excessifs</strong> (épiphora) par absence de contact entre le point lacrymal et la surface oculaire.</li><li><strong>Kératite d'exposition</strong> par assèchement cornéen.</li><li><strong>Conjonctivite chronique</strong> par exposition de la conjonctive.</li><li><strong>Infection oculaire</strong> secondaire.</li><li><strong>Cécité</strong> si kératite non traitée.</li></ul>"},{"i":"e307a08e1517","n":86,"o":"86-1","u":"Diagnostic positif","t":"Reconnaître un ectropion et connaître ses complications","q":"Comment définir cliniquement un ectropion ?","a":"<p>Un ectropion est une <strong>éversion du bord libre de la paupière</strong> (le plus souvent inférieure), exposant la conjonctive palpébrale et la surface oculaire.</p>"},{"i":"540b0ae7bc3f","n":86,"o":"86-11","u":"Prise en charge","t":"Traitement de l’orgelet","q":"Dans quelles situations un traitement antibiotique est-il indiqué pour un orgelet et quelle est sa forme ?","a":"<p>Un traitement antibiotique pour un orgelet est indiqué en cas de <strong>signes d'infection bactérienne surajoutée</strong> ou de persistance de l'orgelet malgré les soins locaux. Il est généralement prescrit <strong>localement</strong> sous forme de <strong>collyre ou de pommade antibiotique</strong>.</p>"},{"i":"deda04174486","n":86,"o":"86-11","u":"Prise en charge","t":"Traitement de l’orgelet","q":"Quand une incision chirurgicale est-elle envisagée pour un orgelet ?","a":"<p>Une incision chirurgicale est envisagée pour un orgelet en cas d'<strong>échec des traitements médicaux</strong> (locaux et/ou antibiotiques) ou si l'orgelet évolue vers la formation d'un <strong>chalazion enkysté</strong> ou d'un <strong>abcès palpébral</strong> persistant et douloureux. Elle vise à drainer le contenu purulent.</p>"},{"i":"f0a4a19002dc","n":86,"o":"86-11","u":"Prise en charge","t":"Traitement de l’orgelet","q":"Quel est le traitement de première intention d'un orgelet ?","a":"<p>Le traitement de première intention d'un orgelet repose sur des mesures locales :</p><ul><li><strong>Compresses chaudes</strong> (4 fois par jour, pendant 10-15 minutes).</li><li><strong>Massages doux</strong> de la paupière pour faciliter le drainage.</li><li><strong>Hygiène locale</strong> rigoureuse (nettoyage au sérum physiologique ou avec des lingettes spécifiques).</li></ul>"},{"i":"13f3a84bc6e3","n":86,"o":"86-12","u":"Identifier une urgence","t":"Savoir évoquer une paralysie du III et rechercher un anévrysme intra-crânien sur un ptosis douloureux","q":"Dans quel contexte clinique doit-on évoquer une paralysie du nerf oculomoteur (III) potentiellement liée à un anévrysme intracrânien ?","a":"<p>On doit évoquer une paralysie du nerf oculomoteur (III) comme une urgence en présence d'un <strong>ptosis douloureux isolé</strong>.</p>"},{"i":"488197066f6f","n":86,"o":"86-12","u":"Identifier une urgence","t":"Savoir évoquer une paralysie du III et rechercher un anévrysme intra-crânien sur un ptosis douloureux","q":"Quelle est la particularité clinique d'une paralysie du III évoquant une compression extrinsèque (comme un anévrysme) par rapport à une ischémie ?","a":"<p>Une paralysie du III d'origine compressive (comme par un anévrysme) se caractérise généralement par une <strong>atteinte intrinsèque du III</strong> (<strong>mydriase aréflective</strong>) associée au ptosis et à la diplopie, contrairement à une atteinte ischémique (<a href=\"https://www.snv.jussieu.fr/vie/dossiers/nerfs-cran/oculomot.htm\">diabète</a> par exemple), qui respecte le plus souvent la fonction pupillaire.</p>"},{"i":"a4620b0075f1","n":86,"o":"86-12","u":"Identifier une urgence","t":"Savoir évoquer une paralysie du III et rechercher un anévrysme intra-crânien sur un ptosis douloureux","q":"Quel diagnostic grave faut-il systématiquement rechercher face à un ptosis douloureux et une suspicion de paralysie du III ?","a":"<p>Face à un ptosis douloureux avec suspicion de paralysie du III, il faut systématiquement rechercher un <strong>anévrysme intracrânien</strong>, notamment au niveau de l'<strong>artère communicante postérieure</strong>.</p>"},{"i":"6ad02afb6bf6","n":86,"o":"86-2","u":"Diagnostic positif","t":"Reconnaître un entropion et connaître ses complications","q":"Définition : qu'est-ce qu'un entropion ?","a":"<p>L'entropion est une malposition de la paupière, le plus souvent inférieure, caractérisée par une <strong>rotation du bord libre palpébral vers l'intérieur</strong>, entraînant un contact des cils et/ou de la peau avec le globe oculaire.</p>"},{"i":"94dbe434c844","n":86,"o":"86-2","u":"Diagnostic positif","t":"Reconnaître un entropion et connaître ses complications","q":"Quelles sont les principales complications d'un entropion non traité ?","a":"<ul><li><strong>Kératite</strong> : ulcérations de la cornée dues au frottement des cils.</li><li><strong>Infection cornéenne</strong>.</li><li><strong>Opacification cornéenne</strong>.</li><li>À terme, risque de <strong>baisse d'acuité visuelle</strong> si la kératite et l'opacification sont importantes et chroniques.</li></ul>"},{"i":"c58ad212afce","n":86,"o":"86-2","u":"Diagnostic positif","t":"Reconnaître un entropion et connaître ses complications","q":"Chez un patient, quels sont les signes évocateurs d'un entropion ?","a":"<ul><li><strong>Irritation oculaire</strong> et sensation de corps étranger.</li><li><strong>Larmoiement</strong> (épiphora).</li><li><strong>Rougeur conjonctivale</strong>.</li><li><strong>Blépharospasme réflexe</strong>.</li><li>Examen clinique : <strong>rotation interne du bord libre palpébral</strong> et généralement des cils frottant la cornée.</li></ul>"},{"i":"3300c1a73c01","n":86,"o":"86-3","u":"Diagnostic positif","t":"Reconnaître un ptosis","q":"Quelle est la définition du ptosis ?","a":"<p>Le ptosis correspond à l'<strong>abaissement unilatéral ou bilatéral de la paupière supérieure</strong>, recouvrant anormalement le globe oculaire.</p>"},{"i":"867fe1c2625a","n":86,"o":"86-3","u":"Diagnostic positif","t":"Reconnaître un ptosis","q":"Comment évaluer le degré d'un ptosis unilatéral ?","a":"<p>Le degré d'un ptosis unilatéral s'évalue en comparant le bord libre de la paupière avec le <strong>limbe supérieur</strong> de la cornée. Normalement, la paupière supérieure recouvre le limbe de <strong>1 à 2 mm</strong>. Le ptosis est objectivé lorsque le recouvrement est <strong>supérieur à 2 mm</strong> ou lorsqu'il existe une <strong>asymétrie significative</strong> entre les deux yeux.</p>"},{"i":"89d36dafe098","n":86,"o":"86-3","u":"Diagnostic positif","t":"Reconnaître un ptosis","q":"Comment évaluer le degré d'un ptosis bilatéral ?","a":"<p>Pour un ptosis bilatéral, le degré d'abaissement est évalué par la <strong>mesure de la fente palpébrale verticale</strong> ainsi que la distance entre le <strong>centre du réflexe cornéen lumineux</strong> et le <strong>bord libre de la paupière supérieure</strong> (MRD1), dont la valeur normale est d'environ <strong>4 à 5 mm</strong>. Une valeur inférieure à 4 mm est évocatrice de ptosis.</p>"},{"i":"21a6da70cf9c","n":86,"o":"86-4","u":"Etiologies","t":"Connaître les principales étiologies d’un ptosis","q":"Quelles sont les étiologies mécaniques ou aponévrotiques d'un ptosis ?","a":"<p>Les étiologies mécaniques et aponévrotiques d'un ptosis incluent :</p><ul><li>Le <strong>ptosis aponévrotique acquis</strong> (le plus fréquent, lié à une désinsertion ou dégénérescence de l'aponévrose du muscle releveur).</li><li>Un <strong>blépharochalasis</strong> sévère (excès de peau palpébrale).</li><li>La présence d'une <strong>tumeur palpébrale ou orbitaire</strong>.</li><li>Un <strong>œdème palpébral chronique</strong>.</li><li>Un <strong>ptosis post-traumatique</strong>.</li></ul>"},{"i":"3488fc41b934","n":86,"o":"86-4","u":"Etiologies","t":"Connaître les principales étiologies d’un ptosis","q":"Quelles sont les étiologies neurogènes classiques d'un ptosis ?","a":"<p>Les étiologies neurogènes d'un ptosis comprennent :</p><ul><li>Une atteinte du <strong>nerf oculomoteur (III)</strong>, d'origine centrale ou périphérique.</li><li>Un <strong>syndrome de Claude Bernard-Horner</strong> (atteinte du système sympathique cervical).</li><li>La <strong>myasthénie</strong> (atteinte de la jonction neuromusculaire).</li><li>Une <strong>paralysie supra-nucléaire progressive</strong>.</li></ul>"},{"i":"398881140c3d","n":86,"o":"86-4","u":"Etiologies","t":"Connaître les principales étiologies d’un ptosis","q":"Quelles sont les étiologies congénitales à considérer face à un ptosis ?","a":"<p>Les causes congénitales de ptosis sont principalement :</p><ul><li>Une <strong>dystrophie du muscle releveur</strong> (ptosis congénital simple, le plus courant).</li><li>Un <strong>syndrome de Marcus Gunn</strong> (syncinésie mandibulo-palpébrale).</li><li>Un <strong>ptose congénital associé à d'autres anomalies oculaires</strong> ou syndromiques.</li></ul>"},{"i":"93b9e7a8d1eb","n":86,"o":"86-4","u":"Etiologies","t":"Connaître les principales étiologies d’un ptosis","q":"Quelles sont les étiologies musculaires ou myogènes pouvant provoquer un ptosis ?","a":"<p>Les principales causes musculaires ou myogènes de ptosis sont :</p><ul><li>La <strong>myasthénie</strong> (bien que liée à la jonction neuromusculaire, elle est souvent classée ici pour ses symptômes musculaires).</li><li>Les <strong>myopathies oculaires</strong> (ex : ophtalmoplégie externe progressive, dystrophie myotonique de Steinert).</li><li>La <strong>ptosis acquis sénile</strong> (dégénérescence du muscle releveur).</li></ul>"},{"i":"339a7fbd4cc1","n":86,"o":"86-5","u":"Diagnostic positif","t":"Reconnaître un chalazion","q":"Quels sont les signes cliniques caractéristiques d'un chalazion ?","a":"<p>Cliniquement, un chalazion se présente sous la forme d'une <strong>tuméfaction sous-cutanée palpable</strong>, de taille variable, <strong>non douloureuse</strong>, non inflammatoire (pas de rougeur ni de chaleur), siégeant dans l'épaisseur de la paupière. Il peut être visible par transillumination à travers la conjonctive tarsale.</p>"},{"i":"457f551f1d9d","n":86,"o":"86-5","u":"Diagnostic positif","t":"Reconnaître un chalazion","q":"Quelle est la principale complication locale à rechercher en cas de chalazion de grande taille ?","a":"<p>Un chalazion de grande taille peut entraîner un <strong>astigmatisme induit</strong>, par compression de la cornée, avec une possible baisse de l'acuité visuelle.</p>"},{"i":"ff70b2bbddcb","n":86,"o":"86-5","u":"Diagnostic positif","t":"Reconnaître un chalazion","q":"Comment définir un chalazion ?","a":"<p>Le chalazion est une <strong>inflammation granulomateuse stérile et chronique</strong> d'une ou plusieurs <strong>glandes de Meibomius</strong> (glandes tarsiennes), faisant suite à l'obstruction de leur canal excréteur.</p>"},{"i":"5f835297cb21","n":86,"o":"86-6","u":"Diagnostic positif","t":"Reconnaître un orgelet","q":"Comment définir cliniquement un orgelet ?","a":"<p>L'orgelet est une <strong>inflammation aiguë et purulente</strong> d'une ou plusieurs <strong>glandes de Zeiss ou de Moll</strong> (glandes sébacées ou sudoripares) du bord libre de la paupière. Il s'agit d'une infection bactérienne, le plus souvent staphylococcique.</p>"},{"i":"6e62fdd82afa","n":86,"o":"86-6","u":"Diagnostic positif","t":"Reconnaître un orgelet","q":"Comment l'évolution spontanée de l'orgelet se manifeste-t-elle généralement ?","a":"<p>L'orgelet évolue généralement vers la <strong>spontanée</strong>, avec évacuation du pus par la base du cil, puis <strong>guérison sans séquelle</strong> en quelques jours à une semaine.</p>"},{"i":"78292da2fc19","n":86,"o":"86-6","u":"Diagnostic positif","t":"Reconnaître un orgelet","q":"Quels sont les signes cliniques locaux permettant de reconnaître un orgelet ?","a":"<ul><li><strong>Nodule (bouton) douloureux, rouge et chaud</strong>, siégeant au bord libre de la paupière (généralement centré sur un cil).</li><li>Initialement aspect inflammatoire diffus, puis formation d'une <strong>pustule jaunâtre</strong> ou d'un point blanc suppuratif.</li><li>Sensation de corps étranger ou de gêne.</li><li>Parfois, œdème localisé de la paupière.</li></ul>"},{"i":"7085b726a5c9","n":86,"o":"86-7","u":"Contenu multimédia","t":"Photographie d’un chalazion","q":"Comment différencier un chalazion d'un orgelet ?","a":"<ul><li>Le <strong>chalazion</strong> est généralement <strong>indolore, chronique</strong> et situé à distance du bord libre de la paupière, résultant de l'obstruction d'une glande de Meibomius.</li><li>L'<strong>orgelet</strong> est une <strong>infection aiguë</strong> (souvent staphylococcique) du follicule pilo-sébacé (glande de Zeiss ou de Moll) ou d'une glande de Meibomius, il est <strong>douloureux, inflammatoire</strong> (rougeur, chaleur, tuméfaction) et situé sur le bord libre de la paupière.</li></ul>"},{"i":"e322e38350dd","n":86,"o":"86-7","u":"Contenu multimédia","t":"Photographie d’un chalazion","q":"Quelle est la définition d'un chalazion ?","a":"<p>Un chalazion est une <strong>inflammation granulomateuse stérile et chronique</strong> d'une ou plusieurs <strong>glandes de Meibomius</strong> (glandes sébacées tarsales) situées dans l'épaisseur de la paupière. Il résulte de l'obstruction du canal excréteur de la glande et de l'accumulation de sébum.</p>"},{"i":"f0c129155c01","n":86,"o":"86-7","u":"Contenu multimédia","t":"Photographie d’un chalazion","q":"Quels sont les signes cliniques caractérisant un chalazion ?","a":"<ul><li>Une <strong>masse sous-cutanée de la paupière</strong>, généralement indolore, non inflammatoire et de consistance ferme.</li><li>Elle est localisée à distance du bord libre de la paupière.</li><li>La palpation peut la faire paraître mobile sous la peau, mais elle est fixée au tarse.</li><li>L'examen par <strong>éversion de la paupière</strong> peut montrer une tuméfaction rougeâtre ou grisâtre sur la conjonctive tarsale.</li><li>Il peut y avoir une gêne visuelle en cas de chalazion de grande taille.</li></ul>"},{"i":"4ff5b37237b5","n":86,"o":"86-8","u":"Contenu multimédia","t":"Photographie d’un orgelet","q":"Qu'est-ce qu'un orgelet ?","a":"<p>L'orgelet est une <strong>inflammation aiguë infectieuse</strong> d'une glande de Zeiss ou de Moll, localisée généralement au niveau du <strong>bord libre de la paupière</strong>. Il s'agit d'une infection bactérienne, le plus souvent due à un <strong>Staphylocoque doré</strong>.</p>"},{"i":"656e8e08f229","n":86,"o":"86-8","u":"Contenu multimédia","t":"Photographie d’un orgelet","q":"Quel est le traitement de première intention d'un orgelet ?","a":"<ul><li><strong>Application de compresses chaudes et humides</strong> plusieurs fois par jour pour favoriser la maturation et le drainage spontané.</li><li><strong>Antiseptiques locaux</strong> (collyre ou pommade ophtalmique) en cas de surinfection.</li><li>Éviter le maquillage et le port de lentilles de contact pendant la phase aiguë.</li><li>En cas de persistance ou de complication, un <strong>drainage chirurgical</strong> peut être envisagé.</li></ul>"},{"i":"8c368a7dcabb","n":86,"o":"86-8","u":"Contenu multimédia","t":"Photographie d’un orgelet","q":"Comment se manifeste un orgelet cliniquement ?","a":"<ul><li><strong>Nodule rouge, douloureux, centré par un cil</strong>, au niveau du bord libre de la paupière.</li><li>Œdème localisé de la paupière.</li><li>Sensation de corps étranger.</li><li>Évolution vers une <strong>collection purulente</strong> qui peut se fistuliser spontanément.</li></ul>"}]};